# connected components over 4-markers and current candidate 2 connectors
from collections import deque
mask={(i,j) for i in range(R) for j in range(C) if cand[i][j] in (2,4)}
seen=set(); comps=[]
for p in mask:
 if p in seen:continue
 q=[p];seen.add(p); comp=[]
 while q:
  i,j=q.pop();comp.append((i,j))
  for n in [(i-1,j),(i+1,j),(i,j-1),(i,j+1)]:
   if n in mask and n not in seen:seen.add(n);q.append(n)
 comps.append(comp)
