def graph_stats(grid, active):
 h,w=len(grid),len(grid[0]); nodes={(i,j) for i in range(h) for j in range(w) if grid[i][j] in active}
 edges=sum(1 for i,j in nodes for ni,nj in ((i+1,j),(i,j+1)) if (ni,nj) in nodes)
 par={p:p for p in nodes}
 def find(x):
  while par[x]!=x: par[x]=par[par[x]];x=par[x]
  return x
 for p in nodes:
  i,j=p
  for q in ((i+1,j),(i,j+1)):
   if q in nodes:
    x,y=find(p),find(q)
    if x!=y:par[x]=y
 comps=len({find(p) for p in nodes})
 return len(nodes),edges,comps,edges-len(nodes)+comps
